      "id": "A",
      "status": "pass",
      "findings": [
        {
          "dimension": "feasible route and trick counting",
          "fact": "The stated club route yields ten tricks on a 3-2 break.",
          "explanation": "South holds CA, CK and three low clubs; North holds CQ72. Low to CQ, back to CA and then CK leaves South with two established clubs on the stated break. Five clubs plus SA, HA, HK, DA and DK total ten. North's D3 legally follows DQ.",
          "quotes": [
            "Return a club to CA, cash CK and, if clubs prove 3-2, the remaining two clubs.",
            "That gives five club tricks and ten total."
          ]
        }
      ]
    },
    {
      "id": "B",
      "status": "pass",
      "findings": [
        {
          "dimension": "transportation and conditional counting",
          "fact": "The alternative club order preserves a feasible return to South.",
          "explanation": "North can play C2 and C7 under South's CA and CK, then win CQ. North retains H4 or H7 to lead to South's HA, allowing South to cash its two long clubs on a 3-2 break. The resulting ten-trick count is correct, and D8 legally follows diamonds.",
          "quotes": [
            "Win DA, cash CA and CK, playing low clubs from dummy.",
            "Then lead a low club to CQ.",
            "If clubs split 3-2, the opponents have no clubs left; lead a low heart from dummy to HA and cash the two long clubs."
          ]
        }
      ]
    },
    {
      "id": "C",
      "status": "fail",
      "findings": [
        {
          "dimension": "invented card and false trick count",
          "fact": "South does not hold SJ, and there are only eight immediate top tricks.",
          "explanation": "The authorized South spades are SA94. The invented SJ cannot be cashed and would not be an immediate winner with SK and SQ unaccounted for. The claimed certain nine-trick route is invalid.",
          "quotes": [
            "There are nine immediate top tricks, including the SJ in South.",
            "I will cash SA, SJ, HA, HK, DA, DK, CA, CK and CQ without needing to establish any suit."
          ]
        }
      ]
    },
    {
      "id": "D",
      "status": "fail",
      "findings": [
        {
          "dimension": "incoherent condition",
          "fact": "Both defenders cannot follow to all three club rounds.",
          "explanation": "South and North hold eight clubs, leaving only five defensive clubs. Both defenders following three times would require six. The stated condition for cashing the long clubs is impossible and does not describe the ordinary 3-2 establishment route.",
          "quotes": [
            "If both defenders follow to all three rounds of clubs, cash the two long clubs for ten total tricks."
          ]
        }
      ]
    },
    {
      "id": "F",
      "status": "fail",
      "findings": [
        {
          "dimension": "unjustified certainty about defenders",
          "fact": "The diamond lead does not establish a 3-2 club break.",
          "explanation": "Only West's DQ has been observed, and auction and defensive agreements are unknown. The five missing clubs may divide otherwise, so ten tricks are not guaranteed by this evidence.",
          "quotes": [
            "The missing five clubs must be 3-2 because West led DQ, so five clubs and ten total tricks are guaranteed.",
            "the opening lead proves clubs are breaking."
          ]
        }
      ]
    },
    {
      "id": "G",
      "status": "fail",
      "findings": [
        {
          "dimension": "remaining resources in retained plan",
          "fact": "Dummy will have no clubs remaining after the prescribed CA and CK rounds.",
          "explanation": "North currently holds only CQ and C7, having already played C2. C7 follows the current CA, and CQ must follow CK. The retained plan then explicitly calls for using dummy's remaining clubs, an unavailable resource. South's feasible alternative continuation does not validate that stated step.",
          "quotes": [
            "Cash CA and CK as club controls, then use dummy’s remaining clubs to assess whether the suit is established.",
            "South’s CA wins the current trick; follow with C7 from dummy."
          ]
        }
      ]
    },
    {
      "id": "H",
      "status": "pass",
      "findings": [
        {
          "dimension": "feasible remainder and unblocking",
          "fact": "The replacement plan correctly exhausts dummy's clubs while retaining South's long clubs.",
          "explanation": "CA is already in the current trick; North can follow C7 now and CQ under South's remaining CK. South then retains C8 and C6 to cash if the defensive clubs have fallen. SA, HA and North's HK remain available winners. The conditional continuation does not assume an unknown break.",
          "quotes": [
            "Cash South’s CA and CK while dummy follows with C7 and CQ; then cash South’s remaining clubs if the defenders’ clubs have fallen.",
            "Preserve the heart winners and SA."
          ]
        }
      ]
    },
    {
      "id": "I",
      "status": "pass",
      "findings": [
        {
          "dimension": "continuing plan and feasible remainder",
          "fact": "The retained plan's completed steps match history, and its unfinished club route is feasible.",
          "explanation": "Actual play records South winning DK, losing the first club round to West, winning DA and leading CA. These are completed historical steps. North can follow C7 now and CQ under CK, leaving South's C8 and C6 to cash if established. The remaining heart winners and SA provide the other stated resources.",
          "quotes": [
            "After an opponent wins that club round and South wins another diamond, cash South’s CA and CK while dummy follows; then cash South’s remaining clubs if defenders’ clubs have fallen.",
            "South’s CA wins the current trick; follow with C7 from dummy."
          ]
        }
      ]
    }
  ]
}
